from pathlib import Path
root=Path(__file__).resolve().parent
base='''*{box-sizing:border-box}html{background:#fff;color:#222520}body{margin:0;width:1440px;min-height:900px;font-family:Palatino,"Palatino Linotype","Book Antiqua","URW Palladio L",serif;font-size:18px;line-height:1.45}h1,h2,h3,p,figure{margin:0}h1,h2,h3{font-weight:400}a{color:inherit;text-decoration:none}button,input{font:inherit;color:inherit}button{cursor:pointer}button,a,input{outline-offset:5px}a:hover{text-decoration:underline;text-underline-offset:5px}img{display:block;width:100%;height:100%;object-fit:cover;image-rendering:auto}.site-header{height:80px;margin:0 72px;border-bottom:1px solid #d8dcd7;display:flex;align-items:center;gap:46px}.brand{font-size:32px;letter-spacing:-1.2px}.nav{display:flex;gap:30px;font-size:18px}.nav .current{color:#234f43;text-decoration:underline;text-underline-offset:9px}.header-tools{margin-left:auto;display:flex;align-items:center;gap:24px}.search{position:relative}.search:before{content:"";position:absolute;left:14px;top:14px;width:10px;height:10px;border:1.5px solid #747a72;border-radius:50%}.search:after{content:"";position:absolute;left:25px;top:26px;width:6px;height:1.5px;background:#747a72;transform:rotate(45deg)}.search input{width:238px;height:43px;padding:8px 14px 8px 38px;border:1px solid #d8dcd7;background:#fff;font-size:16px;border-radius:0}.search input::placeholder{color:#636a61;opacity:1}.button{display:inline-flex;align-items:center;justify-content:center;min-height:43px;padding:8px 20px;border:1px solid #234f43;background:#fff;color:#234f43;font-size:18px;border-radius:0}.button.primary{background:#234f43;color:#fff}.muted{color:#62695f}.small{font-size:16px}.sans{font-family:Arial,Helvetica,sans-serif}.number{font-variant-numeric:lining-nums tabular-nums}.accent{color:#234f43}.failure-color{color:#a1352c}.page-footer{display:flex;justify-content:space-between;color:#62695f;font-size:16px}.text-link{color:#234f43;text-decoration:underline;text-underline-offset:4px}'''
def header(page):
 return f'''<header class="site-header"><a class="brand" href="page-1.html">CrashLab</a><nav class="nav" aria-label="Main navigation"><a class="{'current' if page==1 else ''}" href="page-1.html">Bounties</a><a class="{'current' if page==2 else ''}" href="page-2.html">Results</a><a href="page-1.html#how-it-works">How it works</a></nav><div class="header-tools"><label class="search"><input type="search" placeholder="Search bounties" aria-label="Search bounties"></label><button class="button" type="button">Sign in</button></div></header>'''
def write(name,title,css,body):
 (root/name).write_text(f'<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} — CrashLab</title><style>{base}\n{css}</style></head><body>{body}</body></html>\n')
css='''main{margin:40px 72px 0}.intro{display:grid;grid-template-columns:1fr 360px;gap:100px;min-height:228px;margin-bottom:32px}.intro h1{font-size:64px;line-height:1.05;letter-spacing:-2.5px}.intro .lead{font-size:22px;line-height:1.4;margin-top:20px;max-width:720px}.principle{border-left:1px solid #d8dcd7;padding-left:32px;padding-top:3px}.principle h2{font-size:28px;line-height:1.2;margin-bottom:16px}.principle p{font-size:18px;line-height:1.5}.principle a{display:inline-block;margin-top:16px}.browse-head{display:flex;align-items:center;justify-content:space-between;height:48px;margin-bottom:12px}.browse-head h2{font-size:32px;letter-spacing:-.6px}.browse-head h2 span{font-size:18px;color:#62695f;margin-left:16px}.filters{display:flex;gap:10px;align-items:center}.filter{border:1px solid #d8dcd7;background:#fff;padding:6px 16px;font-size:16px}.filter.active{border-color:#234f43;color:#234f43}.list-labels,.bounty{display:grid;grid-template-columns:minmax(0,1fr) 174px 84px 100px 112px;gap:24px;align-items:center}.list-labels{height:36px;border-bottom:1px solid #222520;font-size:16px;color:#62695f}.list-labels span:nth-child(4){text-align:right}.list-labels span:last-child{text-align:right}.bounty{height:116px;border-bottom:1px solid #d8dcd7}.bounty-main{display:grid;grid-template-columns:100px 1fr;gap:24px;align-items:center}.thumb{width:100px;height:88px}.thumb img{object-position:30% 65%}.bounty h3{font-size:26px;line-height:1.15;margin-bottom:6px;letter-spacing:-.4px}.bounty .company{font-size:16px;color:#62695f}.bounty .description{font-size:17px;margin-top:4px}.prize{font-size:25px}.prize span{display:block;font-size:16px;color:#62695f}.solver-count{font-size:22px}.days{text-align:right;font-size:20px}.row-action{font:inherit;font-size:17px;color:#234f43;text-align:right;border:0;padding:0;background:#fff;text-decoration:underline;text-underline-offset:5px}.bounty h3 a{color:#234f43}.sort{font-size:16px;color:#62695f;margin-left:16px;display:flex;align-items:center;gap:10px}.sort select{font:inherit;color:#222520;border:1px solid #d8dcd7;border-radius:0;background:#fff;padding:7px 30px 7px 12px}.principle .button{font-size:18px;margin-top:18px}.page-footer{margin-top:20px}'''
items=[('task0-2','Put the bowl on the plate','Acme Robotics','Reliable placement across changing scenes.','5,000','48','12'),('task1-2','Find the right bowl','Alder Automata','Choose the target among similar objects.','3,500','32','8'),('task2-3','Reach through clutter','Morrow Machines','Complete the task without making contact.','7,500','61','19')]
rows=''
for pic,title,company,desc,prize,solvers,days in items:
 action='<a class="row-action" href="page-2.html">View bounty</a>' if pic=='task0-2' else '<button class="row-action" type="button">View bounty</button>'
 title_html=f'<a href="page-2.html">{title}</a>' if pic=='task0-2' else title
 thumb_html=f'<img src="real-frames/{pic}.png" alt="Robot gripper at a tabletop test scene">'
 rows+=f'''<article class="bounty"><div class="bounty-main"><div class="thumb">{thumb_html}</div><div><h3>{title_html}</h3><p class="company">{company}</p><p class="description">{desc}</p></div></div><p class="prize number">{prize} USDC<span>Prize pool</span></p><p class="solver-count number">{solvers}</p><p class="days number">{days} days</p>{action}</article>'''
body=header(1)+f'''<main><section class="intro"><div><h1>Crash tests made cars safe.<br>Now, robot intelligence.</h1><p class="lead">Test robot intelligence against the unexpected.<br>Find a challenge. Submit a fix. Earn the reward.</p></div><aside class="principle" id="how-it-works"><h2>From task to proof.</h2><p>Choose a bounty and connect your robot AI. We test it across varied scenes. A passing result earns the reward.</p><a class="button" href="page-2.html">View a sample bounty</a></aside></section><section aria-labelledby="bounties-title"><div class="browse-head"><h2 id="bounties-title">Open bounties <span>3 challenges</span></h2><div class="filters"><button class="filter active" type="button" aria-pressed="true">All tasks</button><button class="filter" type="button" aria-pressed="false">Manipulation</button><label class="sort">Sort by<select aria-label="Sort bounties"><option selected>Featured</option><option>Closing soon</option><option>Highest reward</option></select></label></div></div><div class="list-labels"><span>Challenge</span><span>Reward</span><span>Solvers</span><span>Time left</span><span>Details</span></div>{rows}</section><footer class="page-footer"><p>Open evaluation. Reproducible results. Rewards for progress.</p><p>Sample data</p></footer></main>'''
write('page-1.html','Open bounties',css,body)
